package com.aydindemir.redis; import static org.assertj.core.api.Assertions.assertThat; import java.time.Duration; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import com.aydindemir.redis.service.RedisStringService; import com.aydindemir.redis.support.RedisTestContainerSupport;
@SpringBootTest class RedisStringIntegrationTest extends RedisTestContainerSupport { @Autowired RedisStringService s; @Test void setGetExistsDelete(){s.set("test:string","hello",null);assertThat(s.get("test:string")).contains("hello");assertThat(s.exists("test:string")).isTrue();s.delete("test:string");assertThat(s.exists("test:string")).isFalse();} @Test void ttl(){s.set("test:ttl","value",null);s.expire("test:ttl",Duration.ofSeconds(30));assertThat(s.ttl("test:ttl")).isBetween(1L,30L);} }
